template<typename T>
struct TypeInfo {
    static const char* category() { return "Generic"; }
};

// Partial specialization for pointer pattern (T*)
template<typename T>
struct TypeInfo<T*> {
    static const char* category() { return "Pointer"; }
};

// Partial specialization for const reference pattern (const T&)
template<typename T>
struct TypeInfo<const T&> {
    static const char* category() { return "Const Ref"; }
};

const char* c1 = TypeInfo<int>::category();
const char* c2 = TypeInfo<float*>::category();
const char* c3 = TypeInfo<const char&>::category();
// Function template partial specialization requires delegation to a class template
// as shown above, or function overloading.
